[SysTestTarget(classStr(AdrInvoiceTotals), UnitTestType::Class)]
public final class AdrInvoiceTotalsTest extends SysTestCase
{
}

Method.Source:
/// <summary>
/// 3 x 10.05 at 19 % is 5.7285 and must round to 5.73.
/// </summary>
[SysTestMethod]
public void testCalcLineTaxRounds()
{
    AdrInvoiceLine line;

    line.Qty       = 3;
    line.UnitPrice = 10.05;
    line.TaxPct    = 19;

    this.assertEquals(5.73, new AdrInvoiceTotals().calcLineTax(line));
}
